import java.io.*;import java.util.*;import com.jpexs.decompiler.flash.SWF;import com.jpexs.decompiler.flash.abc.*;import com.jpexs.decompiler.flash.abc.types.*;import com.jpexs.decompiler.flash.abc.avm2.instructions.*;
class InspectCosmos {public static void main(String[] args)throws Exception{SWF s=new SWF(new FileInputStream(args[0]),true);for(ScriptPack p:s.getAS3Packs())if(p.getClassPath().toString().equals(args[1])){ABC a=p.abc;for(String m:args[2].split(",")){MethodBody b=a.findBodyByClassAndName(args[1].substring(args[1].lastIndexOf('.')+1),m);b.getCode().markOffsets();System.out.println("METHOD "+m);int n=0;for(var x:b.getCode().code){String name="";if(x.operands!=null&&x.operands.length>0&&Set.of("getlex","getproperty","callproperty","callpropvoid","setproperty").contains(x.definition.instructionName))name=a.constants.getMultiname(x.operands[0]).toString();if(x.definition.instructionName.equals("pushstring"))name=a.constants.getString(x.operands[0]);System.out.println((n++)+" "+x.getAddress()+" "+x.definition.instructionName+" "+Arrays.toString(x.operands)+" "+name);}}}}}
